<script lang="ts">import{exportLaPostePdf,inspectLaPosteSheet,printLaPoste,selectLaPosteSlots,type LaPosteInspection}from'../laposte/workflow.js';import{LA_POSTE_FORMATS,type LaPosteFormat,type PrinterSdk,type PrintRequest,type PrintRoute,type RasterPreview}from'../print/types.js';export let sdk:PrinterSdk;export let route:PrintRoute|undefined;export let printRequest:Omit<PrintRequest,'document'>|undefined;let format:LaPosteFormat='L24A';let inspection:LaPosteInspection|undefined;let status='';async function load(event:Event){try{const file=(event.currentTarget as HTMLInputElement).files?.[0];if(file)inspection=await inspectLaPosteSheet(sdk,new Uint8Array(await file.arrayBuffer()),format);status=`Found ${inspection?.selected.size??0} occupied stamps.`}catch(error){status=String(error)}}function toggle(id:string,checked:boolean){if(inspection){const ids=new Set(inspection.selected);checked?ids.add(id):ids.delete(id);inspection=selectLaPosteSlots(inspection,ids)}}function raster(canvas:HTMLCanvasElement,value:RasterPreview){canvas.width=value.width;canvas.height=value.height;canvas.getContext('2d')?.putImageData(new ImageData(new Uint8ClampedArray(value.rgba),value.width,value.height),0,0)}async function save(){if(!inspection)return;const data=await exportLaPostePdf(sdk,inspection);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data.slice().buffer],{type:'application/pdf'}));a.download='la-poste-labels.pdf';a.click()}async function print(){if(inspection&&route&&printRequest){const results=await printLaPoste(sdk,inspection,route,printRequest);status=`${results.filter(item=>item.outcome==='completed').length}/${inspection.selected.size} stamps printed through ${route.label}.`}}</script>
<section><h2>La Poste sheets</h2><label>Format<select bind:value={format}>{#each LA_POSTE_FORMATS.filter(item=>item!=='SHEET') as item}<option>{item}</option>{/each}</select></label><label class="upload">Choose A4 PDF<input type="file" accept="application/pdf" on:change={load}></label><p aria-live="polite">{status}</p>{#if inspection}<div class="slots">{#each inspection.slots.filter(slot=>slot.occupied) as slot}<label><input type="checkbox" checked={inspection.selected.has(slot.id)} on:change={e=>toggle(slot.id,e.currentTarget.checked)}><canvas use:raster={slot.preview} aria-label={`Preview page ${slot.sourcePage} slot ${slot.slot}`}></canvas><span>Page {slot.sourcePage}, slot {slot.slot}<small>63.5 × 33.9 mm</small></span></label>{/each}</div><button on:click={save} disabled={!inspection.selected.size}>Export selected PDF</button><button on:click={print} disabled={!inspection.selected.size||!route||!printRequest}>Print selected via {route?.label??'selected route'}</button>{/if}</section>
<style>section{padding:.75rem;border-top:1px solid var(--mble-border,#ddd)}h2{font-size:.8rem;text-transform:uppercase}.upload{display:block;border:1px solid var(--mble-border-strong,#bbb);padding:.4rem}.upload input{position:absolute;opacity:0;width:1px}.slots{display:grid;grid-template-columns:1fr 1fr;gap:.35rem;max-height:14rem;overflow:auto}.slots label{display:flex;gap:.2rem;background:var(--mble-surface-muted,#f7f4ed);padding:.3rem}.slots canvas{width:4rem;height:2.2rem;object-fit:contain;background:white}.slots small{display:block}</style>
